"""Embedded AI Studio Photos and Quiet FX Audio Assets for Guess The Colour."""
import io
import base64
import pygame

IMAGES = {
    'blue_blueberries': '',
    'green_apple': '',
    'orange_fruit': '',
    'pink_cherry_blossom': '',
    'purple_lavender': '',
    'red_strawberry': '',
    'white_daisy': '',
    'yellow_sunflower': '',
}

SFX = {
    'badge': '',
    'bloom': '',
    'card_flip': '',
    'celebrate': '',
    'click': '',
    'correct': '',
    'gentle_hint': '',
    'hover': '',
    'pop': '',
    'tap': '',
}


ALIASES = {
    "strawberry": "red_strawberry",
    "red_strawberry": "red_strawberry",
    "sunflower": "yellow_sunflower",
    "yellow_sunflower": "yellow_sunflower",
    "orange": "orange_fruit",
    "orange_fruit": "orange_fruit",
    "lavender": "purple_lavender",
    "purple_lavender": "purple_lavender",
    "green_apple": "green_apple",
    "apple": "green_apple",
    "blue_blueberries": "blue_blueberries",
    "blueberries": "blue_blueberries",
    "pink_cherry_blossom": "pink_cherry_blossom",
    "cherry_blossom": "pink_cherry_blossom",
    "white_daisy": "white_daisy",
    "daisy": "white_daisy",
}


def load_image(item_id):
    key = ALIASES.get(item_id, item_id)
    if key in IMAGES:
        data = base64.b64decode(IMAGES[key])
        bio = io.BytesIO(data)
        surf = pygame.image.load(bio)
        if pygame.display.get_surface():
            return surf.convert_alpha()
        return surf
    return None

def load_sound(sfx_id):
    if sfx_id in SFX:
        data = base64.b64decode(SFX[sfx_id])
        bio = io.BytesIO(data)
        try:
            return pygame.mixer.Sound(bio)
        except Exception:
            return None
    return None
